class PageUtil:

    def __init__(self, data, page_size):
        self.data = data
        self.page_size = page_size
        self.total_items = len(data)
        self.total_pages = (self.total_items + page_size - 1) // page_size

    def get_page(self, page_number):
        """Retrieve a specific page of data.
        :param page_number: int, the page number to fetch
        :return: list, the data on the specified page
        """
        if page_number < 1 or page_number > self.total_pages:
            return []
        start_index = (page_number - 1) * self.page_size
        end_index = start_index + self.page_size
        return self.data[start_index:end_index]

    def get_page_info(self, page_number):
        """Retrieve information about a specific page.
        :param page_number: int, the page number to fetch information about
        :return: dict, containing page information such as current page number, total pages, total items, etc.
        """
        if page_number < 1 or page_number > self.total_pages:
            raise ValueError('Invalid page number')
        start_index = (page_number - 1) * self.page_size
        end_index = start_index + self.page_size
        current_page_data = self.data[start_index:end_index]
        has_previous = page_number > 1
        has_next = page_number < self.total_pages
        return {'current_page': page_number, 'per_page': self.page_size, 'total_pages': self.total_pages, 'total_items': self.total_items, 'has_previous': has_previous, 'has_next': has_next, 'data': current_page_data}

    def search(self, keyword):
        if not keyword:
            return {'keyword': keyword, 'total_results': self.total_items, 'total_pages': self.total_pages, 'results': self.data}
        matching_items = [item for item in self.data if str(keyword).lower() in str(item).lower()]
        total_results = len(matching_items)
        total_pages = (total_results + self.page_size - 1) // self.page_size
        return {'keyword': keyword, 'total_results': total_results, 'total_pages': total_pages, 'results': matching_items}

